#!/usr/bin/env python3
# Pinneberg-Automatik: Gain 49.6, lesbarer Text, Tag 07-17 Uhr.
# Kein Mesh, kein Alarm. Stick 3 bleibt der registrierte Stick.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
BASIS = {
    "pinneberg_rx.py": "dd77d98ca4efd535",
    "pinneberg_rolle.py": "339b2572dee7b9d3",
    "prepper_sdr.py": "99aeac19adae6a99",
    "dashboard.py": "2434c1aabc620d95",
}
LAENGE = {
    "pinneberg_rx.py": 25486,
    "prepper_sdr.py": 778377,
    "dashboard.py": 1387534,
}
PATCH = ("pinneberg_rx.py", "pinneberg_rolle.py")
GUARD = ("pinneberg_rx.py", "pinneberg_rolle.py", "prepper_sdr.py", "dashboard.py")


def load():
    raw = PAYLOAD_JSON
    return {name: (base64.b64decode(raw[key]["old"]), base64.b64decode(raw[key]["new"]))
            for name, key in (("pinneberg_rx.py", "rx"), ("pinneberg_rolle.py", "rolle"))}


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return 5 <= m <= 39, "Berlin Minute %02d" % m


def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-pbauto-*"))
    bak = path.with_name(path.name + ".bak-pbauto-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass


def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-pbauto")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass


def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare = load()
    blobs = {}
    for name in GUARD:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        print("%s sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
    ziel = {}
    for name in PATCH:
        alt, neu = paare[name]
        if blobs[name] == neu:
            ziel[name] = neu
        elif blobs[name] == alt:
            ziel[name] = neu
        else:
            print("STOP: %s %s / %d passt nicht zum Stand %s. Nichts geschrieben." % (name, sha(blobs[name])[:16], len(blobs[name]), BASIS[name]))
            return 2
    falsch = False
    for name in GUARD:
        if name in ziel and blobs[name] == ziel[name]:
            continue
        ist = sha(blobs[name])
        if not ist.startswith(BASIS[name]) or (name in LAENGE and len(blobs[name]) != LAENGE[name]):
            print("STOP: %s %s / %d ist nicht der Pi-Stand %s." % (name, ist[:16], len(blobs[name]), BASIS[name]))
            falsch = True
    if falsch:
        print("STOP: Hash-Guard. Nichts geschrieben.")
        return 2
    try:
        compile(ziel["pinneberg_rx.py"], "pinneberg_rx.py", "exec")
        compile(ziel["pinneberg_rolle.py"], "pinneberg_rolle.py", "exec")
    except SyntaxError as exc:
        print("STOP: Syntax %s" % exc)
        return 2
    if b'"-g"' not in ziel["pinneberg_rx.py"] or b"49.6" not in ziel["pinneberg_rx.py"] or b'"-E", "dc"' not in ziel["pinneberg_rx.py"]:
        print("STOP: Gain fehlt")
        return 2
    if "Empfang läuft, noch kein lesbarer Text".encode() not in ziel["pinneberg_rx.py"] or b"def lesbar" not in ziel["pinneberg_rx.py"]:
        print("STOP: Textfilter fehlt")
        return 2
    if b"127645000" not in ziel["pinneberg_rx.py"] or b"DAY_START = 7 * 60" not in ziel["pinneberg_rx.py"]:
        print("STOP: Tagfenster fehlt")
        return 2
    for name in PATCH:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    for name in ("prepper_sdr.py", "dashboard.py"):
        print("%s unveraendert sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    frei, meldung = fenster(jetzt)
    print(meldung)
    if all(blobs[name] == ziel[name] for name in PATCH):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        if not frei:
            print("Ein echtes Apply wuerde in dieser Minute ohne Aenderung abbrechen.")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in PATCH:
            if blobs[name] != ziel[name]:
                sichern(ordner / name, blobs[name])
                schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. prepper-sdr und prepper-dashboard neu starten.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("Dateien sind neu. Der Neustart bleibt aus, die Minute ist nicht mehr 05-39.")
        return 2
    subprocess = __import__("subprocess")
    subprocess.run(["systemctl", "restart", "prepper-sdr.service"], check=False)
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("prepper-sdr und prepper-dashboard neu gestartet.")
    return 0


def selftest() -> int:
    assert BASIS["pinneberg_rx.py"] == "dd77d98ca4efd535" and LAENGE["pinneberg_rx.py"] == 25486
    assert BASIS["pinneberg_rolle.py"] == "339b2572dee7b9d3"
    assert BASIS["prepper_sdr.py"] == "99aeac19adae6a99" and LAENGE["prepper_sdr.py"] == 778377
    assert BASIS["dashboard.py"] == "2434c1aabc620d95" and LAENGE["dashboard.py"] == 1387534
    assert fenster(datetime(2026, 11, 20, 22, 12))[0]
    assert fenster(datetime(2026, 11, 20, 22, 5))[0] and fenster(datetime(2026, 11, 20, 22, 39))[0]
    assert not fenster(datetime(2026, 11, 20, 22, 4))[0] and not fenster(datetime(2026, 11, 20, 22, 40))[0]
    neu = load()["pinneberg_rx.py"][1]
    ns = {}
    exec(compile(neu, "pinneberg_rx.py", "exec"), ns)
    assert ns["lesbar"]("PXKXKEKGGLILPIVLWPVVVVMVVVV") is False
    assert ns["lesbar"]("DWD SEEWETTER WIND BOE SEE HPA 1013 NORD") is True
    assert ns["plan"](__import__("datetime").datetime(2026, 11, 12, 12, 0, tzinfo=__import__("zoneinfo").ZoneInfo("Europe/Berlin")).timestamp())["tune_hz"] == 127645000
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="pbauto-"))
    for name in GUARD:
        (ordner / name).write_bytes(b"falsch")
    vorher = {name: (ordner / name).read_bytes() for name in GUARD}
    assert apply_dir(ordner, True, True, datetime(2026, 11, 20, 22, 12)) == 2
    assert vorher == {name: (ordner / name).read_bytes() for name in vorher}
    print("selftest ok")
    return 0


def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)


PAYLOAD_JSON = {"rx": {"old": "", "new": ""}, "rolle": {"old": "", "new": ""}}


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
